public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    int length1 = word1.length();
    int length2 = word2.length();
    int commonCount = 0;

    boolean[] usedInWord2 = new boolean[length2];

    for (int i = 0; i < length1; i++) {
        char c1 = word1.charAt(i);
        for (int j = 0; j < length2; j++) {
            if (!usedInWord2[j] && c1 == word2.charAt(j)) {
                commonCount++;
                usedInWord2[j] = true;
                break;
            }
        }
    }

    int totalLength = length1 + length2;
    int gcd = gcd(commonCount, totalLength);

    String result = "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (totalLength / gcd);
    return result;
}

