public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int openCount = 0; // To count the number of unmatched '('
    int insertions = 0; // To count the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            openCount++;
        } else if (c == ')') {
            if (openCount > 0) {
                openCount--; // Match with an existing '('
            } else {
                insertions++; // Need to insert a '(' to match this ')'
            }
            // Check for consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it is matched
            } else {
                insertions++; // Need to insert a ')' to match the current '('
            }
        }
    }

    // Add remaining unmatched '('
    insertions += openCount * 2;

    return insertions;
}

