public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    while (b <= k) {
        fibs.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    // Use the largest possible Fibonacci numbers to sum up to k
    for (int i = fibs.size() - 1; i >= 0 && k > 0; i--) {
        while (k >= fibs.get(i)) {
            k -= fibs.get(i);
            count++;
        }
    }

    return count;
}

